    if(entered){if(!promo.enabled||entered!==String(promo.coupon).toUpperCase())state='invalid';else if(subtotal<Number(promo.couponMin))state='minimum';else{state='applied';couponAmount=Math.round(subtotal*Number(promo.couponPercent))/100}}
    var discount=Math.min(subtotal,Math.max(auto,couponAmount)),after=Math.round((subtotal-discount)*100)/100,fee=shipping(type);if(promo.enabled&&type!=='pickup'&&after>=Number(promo.freeDeliveryAt))fee=0;
