    document.querySelectorAll('#p0 .pc').forEach(function(card){var name=card.querySelector('.n'),price=card.querySelector('.pr');if(!name||!price)return;var item=product(name.textContent);if(!item)return;var percent=offerFor(item),badge=card.querySelector('.com-offer-badge');if(percent){if(!badge){badge=document.createElement('span');badge.className='com-offer-badge';price.before(badge)}var label=percent+'% '+word('ছাড়','off');if(badge.textContent!==label)badge.textContent=label;var newPrice=item.price*(100-percent)/100,markup='<del>'+money(item.price)+'</del> <strong>'+money(newPrice)+'</strong>';if(price.innerHTML!==markup)price.innerHTML=markup}else{if(badge)badge.remove();var normal=money(item.price);if(price.textContent!==normal)price.textContent=normal}});
