      body('<form id="com-cake" class="com-form">'+
        '<label class="com-field">'+word('সাইজ','Size')+'<select name="size"><option value="1">1 kg · ৳1200</option><option value="2">2 kg · ৳2200</option><option value="3">3 kg · ৳3200</option></select></label>'+
        '<label class="com-field">'+word('ফ্লেভার','Flavour')+'<select name="flavour"><option value="Chocolate">Chocolate</option><option value="Vanilla">Vanilla</option><option value="Red Velvet">Red Velvet + ৳200</option></select></label>'+
        '<label class="com-field">'+word('ডিম ছাড়া','Egg free')+'<select name="egg"><option value="no">'+word('না','No')+'</option><option value="yes">'+word('হ্যাঁ, + ৳200','Yes, + ৳200')+'</option></select></label>'+
        '<label class="com-field">'+word('পরিমাণ','Quantity')+'<input name="qty" type="number" min="1" max="5" value="1" required></label>'+
        '<label class="com-field full">'+word('কেকে লেখা','Message on cake')+'<input name="message" maxlength="60" placeholder="'+word('যেমন: শুভ জন্মদিন','For example: Happy Birthday')+'"></label>'+
        '<div class="com-field full"><div class="com-note">'+word('উপাদানে দুধ, গম ও বাদাম থাকতে পারে। অ্যালার্জি থাকলে checkout note-এ জানান। কাস্টম কেকের জন্য কমপক্ষে ২৪ ঘণ্টা আগে অর্ডার করুন।','May contain milk, wheat and nuts. Mention allergies in the checkout note. Order custom cakes at least 24 hours ahead.')+'</div><div id="com-cake-price" class="com-summary"></div><div class="com-bottom"><button class="com-button primary" type="submit">'+word('চেকআউটে যান','Continue to checkout')+'</button></div></div></form>');updateCakePrice();
