  function updateCakePrice(){var form=document.getElementById('com-cake');if(!form)return;var price=({1:1200,2:2200,3:3200})[form.elements.size.value]+(form.elements.flavour.value==='Red Velvet'?200:0)+(form.elements.egg.value==='yes'?200:0);document.getElementById('com-cake-price').innerHTML='<div class="total"><span>'+word('মোট','Total')+'</span><span>'+money(price*Number(form.elements.qty.value||1))+'</span></div>'}
  function appointmentSlots(date){return ['10:00','11:00','12:00','15:00','16:00'].map(function(slot){var used=bookings.filter(function(x){return x.date===date&&x.slot===slot&&x.status!=='cancelled'}).length;return {name:slot,left:Math.max(0,4-used)}})}
  function updateBookingSlots(){var form=document.getElementById('com-booking');if(!form)return;var current=form.elements.slot.value;var options=appointmentSlots(form.elements.date.value).filter(function(x){return x.left>0});form.elements.slot.innerHTML=options.map(function(x){return '<option value="'+x.name+'">'+x.name+' · '+x.left+' '+word('সিট বাকি','places left')+'</option>'}).join('');if(options.some(function(x){return x.name===current}))form.elements.slot.value=current}
  function createCake(form){var d=new FormData(form),size=Number(d.get('size')),flavour=d.get('flavour'),egg=d.get('egg')==='yes',qty=Number(d.get('qty')),unit=({1:1200,2:2200,3:3200})[size]+(flavour==='Red Velvet'?200:0)+(egg?200:0);checkoutLines=[{id:'custom-cake',name:'Custom Cake',qty:qty,unit:unit,detail:size+' kg · '+flavour+(egg?' · Egg free':'')+(d.get('message')?' · '+String(d.get('message')).trim():''),rxNeeded:false}];view='checkout';render()}
  function createBooking(form){var d=new FormData(form),date=d.get('date'),slot=d.get('slot'),availableSlot=appointmentSlots(date).find(function(x){return x.name===slot});if(!availableSlot||!availableSlot.left){document.getElementById('com-error').textContent=word('এই সময়টি পূর্ণ। অন্য সময় বেছে নিন।','That time is full. Choose another.');updateBookingSlots();return}var booking={id:'E-'+Date.now().toString(36).toUpperCase(),name:String(d.get('name')).trim(),phone:String(d.get('phone')).trim(),date:date,slot:slot,note:String(d.get('note')||'').trim(),status:'pending',created:new Date().toISOString()};bookings.unshift(booking);save('bookings',bookings);lastPhone=booking.phone;save('phone',lastPhone);window.comLastBooking=booking.id;view='booking-done';render()}
  function renderBookingDone(){var booking=bookings.find(function(x){return x.id===window.comLastBooking});header(word('বুকিং অনুরোধ পাঠানো হয়েছে','Booking requested'),booking?booking.id:'');body('<div class="com-note">'+word('Owner নিশ্চিত করার পর “আমার অর্ডার”-এ status দেখুন।','Check “My orders” for confirmation from the Owner.')+'</div><div class="com-bottom">'+button('orders','আমার বুকিং দেখুন','View my booking',true)+'</div>')}
  function renderCompare(){
    var frames=CATS.filter(function(c){return c[0]==='frames'||c[0]==='sun'}).flatMap(function(c){return c[2].map(function(p){return {category:c,product:p,item:product(p[0])}})});
    if(!compareIds.length)compareIds=[frames[0].item.id,frames[1].item.id];
    header(word('ফ্রেম তুলনা','Compare frames'),word('দাম ও মুখের আকৃতির মিল পাশাপাশি দেখুন','Compare prices and face-shape matches'));
    var choices=compareIds.map(function(id,index){return '<label class="com-field">'+word('ফ্রেম ','Frame ')+(index+1)+'<select data-compare="'+index+'">'+frames.map(function(x){return '<option value="'+esc(x.item.id)+'"'+(id===x.item.id?' selected':'')+'>'+esc(x.item.name)+'</option>'}).join('')+'</select></label>'}).join('');
    var selected=compareIds.map(function(id){return frames.find(function(x){return x.item.id===id})});
    body('<div class="com-form">'+choices+'</div><div class="com-metrics" style="grid-template-columns:repeat(2,1fr)">'+selected.map(function(x){var match=typeof cvMatch==='function'?cvMatch(x.category,x.product):-1;return '<div><strong>'+esc(x.item.name)+'</strong><b>'+money(x.item.price)+'</b><span>'+word('ক্যাটেগরি: ','Category: ')+esc(x.category[1])+'</span><br><span>'+word('মুখের আকৃতির মিল: ','Face-shape match: ')+(match>=0?match+'%':'—')+'</span><br><span>'+word('স্টক: ','Stock: ')+available(x.item.id)+'</span><br><button class="com-button" type="button" data-com="compare-add" data-id="'+esc(x.item.id)+'">'+word('কার্টে যোগ করুন','Add to cart')+'</button></div>'}).join('')+'</div><div class="com-note">'+word('এই match একটি style suggestion; চশমার আসল fit নির্ভর করে lens width, bridge ও temple মাপের ওপর। কেনার আগে শোরুমে মাপ যাচাই করুন।','The match is a style suggestion. Actual fit depends on lens width, bridge and temple size. Confirm measurements at the showroom before purchase.')+'</div>');
  }
  function statusLabel(code){return ({pending:word('অপেক্ষমাণ','Pending'),accepted:word('গৃহীত','Accepted'),processing:bakery?word('তৈরি হচ্ছে','Baking'):word('ল্যাবে তৈরি হচ্ছে','In lab'),ready:word('প্রস্তুত','Ready'),out:word('ডেলিভারিতে','Out for delivery'),completed:word('সম্পন্ন','Completed'),cancelled:word('বাতিল','Cancelled')})[code]||code}
  function statusNext(code){return ({pending:['accepted','cancelled'],accepted:['processing','cancelled'],processing:['ready'],ready:['out','completed'],out:['completed'],completed:[],cancelled:[]})[code]||[]}
