  function renderDone(){var order=orders.find(function(x){return x.id===window.comLastOrder});header(word('অর্ডার নেওয়া হয়েছে','Order placed'),order?order.id:'');body('<div class="com-note">'+word('অর্ডার এই ব্রাউজারে সংরক্ষিত হয়েছে। স্ট্যাটাস দেখতে “আমার অর্ডার” খুলুন।','The order is saved in this browser. Open “My orders” to track it.')+'</div><div class="com-summary"><div><span>'+word('মোট','Total')+'</span><b>'+money(order&&order.total)+'</b></div><div><span>'+word('বর্তমান অবস্থা','Current status')+'</span><b>'+statusLabel(order&&order.status)+'</b></div></div><div class="com-bottom">'+button('orders','আমার অর্ডার দেখুন','View my orders',true)+'</div>')}
  function orderCard(order,admin){return '<div class="com-row"><div><strong>#'+esc(order.id)+' <span class="com-status">'+statusLabel(order.status)+'</span></strong><div class="com-muted">'+esc(order.lines.map(function(x){return x.name+' × '+x.qty}).join(', '))+'</div><div class="com-muted">'+esc(order.date)+' · '+esc(order.slot)+' · '+esc(order.name)+' · '+esc(order.phone)+'</div><div class="com-muted">'+word('পেমেন্ট: ','Payment: ')+(order.paymentStatus==='paid'?word('পরিশোধিত','Paid'):word('বাকি','Unpaid'))+(order.rxName?' · Rx: '+esc(order.rxName):'')+'</div></div><span class="com-price">'+money(order.total)+'</span></div>'+(admin?'<div class="com-actions">'+statusNext(order.status).map(function(s){return '<button type="button" data-com="status" data-id="'+esc(order.id)+'" data-status="'+s+'">'+statusLabel(s)+'</button>'}).join('')+(order.paymentStatus!=='paid'?'<button type="button" data-com="paid" data-id="'+esc(order.id)+'">'+word('পেমেন্ট পেয়েছি','Mark paid')+'</button>':'')+(order.rxName?'<button type="button" data-com="rx" data-id="'+esc(order.id)+'">'+word('Rx ফাইল খুলুন','Open Rx')+'</button>':'')+'</div>':'<div class="com-muted">'+order.history.map(function(h){return statusLabel(h.status)+' · '+new Date(h.at).toLocaleString(language()==='en'?'en-BD':'bn-BD')}).join(' → ')+'</div>')}
  function renderOrders(){header(word('আমার অর্ডার','My orders'),word('এই ব্রাউজারে করা অর্ডার দেখুন','Orders placed in this browser'));var list=orders.filter(function(x){return x.phone===lastPhone}),mine=bookings.filter(function(x){return x.phone===lastPhone});body('<label class="com-field">'+word('অর্ডারের মোবাইল নম্বর','Order mobile number')+'<input id="com-phone" inputmode="tel" pattern="01[0-9]{9}" value="'+esc(lastPhone)+'" placeholder="01XXXXXXXXX"></label><div class="com-note">'+word('এই demo-তে একই ব্রাউজারের অর্ডার দেখা যায়। বাস্তব customer login পরে সার্ভারে যুক্ত করতে হবে।','This demo shows orders from this browser. Real customer login requires a server.')+'</div>'+(list.length?list.map(function(x){return orderCard(x,false)+'<div class="com-actions">'+orderDetailsButton(x.id)+'</div>'}).join(''):'<div class="com-empty">'+word('এই নম্বরে কোনো পণ্য অর্ডার নেই।','No product orders for this number.')+'</div>')+(mine.length?'<h3>'+word('চোখ পরীক্ষার বুকিং','Eye exam bookings')+'</h3>'+mine.map(function(x){return bookingCard(x,false)}).join(''):''))}
