  function renderSlots(){var input=document.getElementById('com-slot-date'),area=document.getElementById('com-slot-list');if(!input||!area)return;area.innerHTML=slots(input.value).map(function(x){return '<div class="com-row"><strong>'+x.name+'</strong><span>'+x.left+' / 8 '+word('স্লট বাকি','places left')+'</span></div>'}).join('')}
  function changeStatus(id,status){var order=orders.find(function(o){return o.id===id});if(!order||statusNext(order.status).indexOf(status)<0)return;if(status==='processing'&&order.rxName&&!order.rxVerified){notice(word('ল্যাব শুরু করার আগে Rx যাচাই করুন','Verify the prescription before starting lab work'));return}if(status==='cancelled'){order.lines.forEach(function(x){stock[x.id]=available(x.id)+x.qty});save('stock',stock);refreshAvailability()}order.status=status;order.history.push({status:status,at:new Date().toISOString()});save('orders',orders);render()}
