    if(!overlay.hidden){if(e.target===overlay){close();return}var action=e.target.closest('[data-com]');if(action){var a=action.dataset.com,i=Number(action.dataset.index);if(a==='close')close();else if(a==='cart'){checkoutLines=null;view='cart';render()}else if(a==='checkout'){checkoutLines=null;view='checkout';render()}else if(a==='orders'){view='orders';render()}else if(a==='compare-add'){var compareItem=products.find(function(x){return x.id===action.dataset.id});if(compareItem)add({id:compareItem.id,name:compareItem.name,qty:1,unit:compareItem.price,detail:'',rxNeeded:false})}else if(a==='qty'){var x=cart[i];if(x){var n=x.qty+Number(action.dataset.delta);if(n<1)cart.splice(i,1);else if(n<=available(x.id))x.qty=n;else notice(word('স্টক সীমা ছাড়িয়েছে','Stock limit reached'));save('cart',cart);updateBadge();render()}}else if(a==='remove'){cart.splice(i,1);save('cart',cart);updateBadge();render()}else if(a==='admin-tab'){adminTab=action.dataset.tab;render()}else if(a==='status')changeStatus(action.dataset.id,action.dataset.status);else if(a==='booking-status'){var booking=bookings.find(function(x){return x.id===action.dataset.id});if(booking&&((booking.status==='pending'&&['accepted','cancelled'].includes(action.dataset.status))||(booking.status==='accepted'&&action.dataset.status==='completed'))){booking.status=action.dataset.status;save('bookings',bookings);render()}}else if(a==='paid'){var o=orders.find(function(x){return x.id===action.dataset.id});if(o){o.paymentStatus='paid';save('orders',orders);render()}}else if(a==='rx'){fileGet(action.dataset.id).then(function(file){if(!file){notice(word('ফাইল পাওয়া যায়নি','File not found'));return}var url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download=file.name||'prescription';link.click();setTimeout(function(){URL.revokeObjectURL(url)},30000)})}return}}
    var promoButton=e.target.closest('[data-promo-category]');if(promoButton){e.preventDefault();e.stopPropagation();cvOpen(promoButton.dataset.promoCategory);return}
