  overlay.addEventListener('submit',function(e){if(e.target.id==='com-checkout'){e.preventDefault();place(e.target)}else if(e.target.id==='com-cake'){e.preventDefault();createCake(e.target)}else if(e.target.id==='com-booking'){e.preventDefault();createBooking(e.target)}else if(e.target.id==='com-promo-form'){e.preventDefault();var d=new FormData(e.target),next={enabled:d.get('enabled')==='yes',group:String(d.get('group')),percent:Number(d.get('percent')),coupon:String(d.get('coupon')).trim().toUpperCase(),couponPercent:Number(d.get('couponPercent')),couponMin:Number(d.get('couponMin')),freeDeliveryAt:Number(d.get('freeDeliveryAt'))};if(!CATS.some(function(c){return c[0]===next.group})||next.percent<1||next.percent>50||next.couponPercent<1||next.couponPercent>50)return;if(next.coupon!==promo.coupon){coupon='';save('coupon',coupon)}promo=next;save('promotion',promo);refreshPromotions();render();notice(word('অফার সংরক্ষিত হয়েছে','Promotion saved'))}});
